const tabId = 1962625065;

const dealers = await browserjs(tabId, () => {
  // Let's inspect dealer elements
  const cards = document.querySelectorAll('.dealer-card, [class*="dealer-card"], [data-qa*="dealer-card"]');

  // If cards aren't matched by class, let's find all dealer blocks
  const results = [];

  // Let's look for dealer headings and their containers
  const headings = Array.from(document.querySelectorAll('h2'));
  for (const h of headings) {
    const card = h.closest('div[class*="dealer"], article, section') || h.parentElement;

    // Rating
    const ratingEl = card.querySelector('[aria-label*="star"], [class*="rating"], [aria-label*="rating"]');
    const ratingText = ratingEl?.getAttribute('aria-label') || ratingEl?.innerText;

    // Reviews
    const reviewEl = card.querySelector('a[href*="reviews"], [class*="review"]');

    // Distance & Address
    const distanceEl = Array.from(card.querySelectorAll('*')).find(el => el.children.length === 0 && el.innerText?.includes('miles away'));
    const addressEl = card.querySelector('a[href*="maps"], [class*="address"]');

    results.push({
      name: h.innerText?.trim(),
      ratingAttr: ratingEl?.getAttribute('aria-label'),
      ratingText: ratingText?.trim(),
      reviews: reviewEl?.innerText?.trim(),
      distance: distanceEl?.innerText?.trim(),
      fullText: card.innerText?.trim()
    });
  }
  return results;
});

console.log(JSON.stringify(dealers, null, 2));

